<section class="panel" id="products"><div class="section-title"><div><div class="eyebrow">Catalogue</div><h2><?= $editingProduct ? 'Edit product.' : 'Add a product.' ?></h2></div><p>Upload product photography directly to Supabase Storage.</p></div><form class="product-form" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=admin_h($csrfToken)?>"><input type="hidden" name="product_id" value="<?=admin_h($editingProduct['id'] ?? '')?>"><div class="field"><label>Product name</label><input name="name" maxlength="160" value="<?=admin_h($editingProduct['name'] ?? '')?>" required></div><div class="field"><label>Price in NGN</label><input name="price" type="number" min="0.01" step=".01" value="<?= $editingProduct ? admin_h(number_format($editingProduct['price_kobo'] / 100, 2, '.', '')) : '' ?>" required></div><div class="field full"><label>Description</label><textarea name="description" maxlength="5000" placeholder="What does this scent feel like?"><?=admin_h($editingProduct['description'] ?? '')?></textarea></div><div class="field"><label>Product image upload</label><input name="image" type="file" accept="image/jpeg,image/png,image/webp"><small>JPEG, PNG or WebP. Maximum 5MB.</small><?php if (!empty($editingProduct['image_url'])): ?><small>Current image remains unless replaced.</small><?php endif; ?></div><div class="field"><label>Image URL fallback</label><input name="image_url" type="url" maxlength="500" placeholder="https://..." value="<?=admin_h($editingProduct['image_url'] ?? '')?>"><small>An uploaded file takes priority.</small></div><div class="field"><label>Stock</label><input name="stock" type="number" min="0" value="<?=($editingProduct && $editingProduct['stock'] !== null) ? admin_h($editingProduct['stock']) : ''?>" placeholder="Blank = unlimited"></div><div class="field full form-actions"><button class="primary" name="save" value="1"><?= $editingProduct ? 'Save product changes' : 'Publish product' ?></button><?php if ($editingProduct): ?><a class="cancel" href="/admin/products">Cancel edit</a><?php endif; ?></div></form></section>
<section class="panel"><div class="section-title"><div><div class="eyebrow">Current collection</div><h2>Your products.</h2></div><p>Hide a product when it is unavailable without deleting its history.</p></div><div class="product-list"><?php if (!$products): ?><p style="color:var(--muted)">No products yet. Your first product can start the collection.</p><?php endif; ?><?php foreach ($products as $p): ?><div class="product-row"><?php if ($p['image_url']): ?><img class="thumb" src="<?=admin_h($p['image_url'])?>" alt=""><?php else: ?><span class="thumb-placeholder">BL</span><?php endif; ?><div><h3><?=admin_h($p['name'])?></h3><p><?=admin_h($p['active'] ? 'Published' : 'Hidden')?> · <?= $p['stock'] === null ? 'Unlimited stock' : (int) $p['stock'] . ' in stock' ?></p><div class="row-actions"><a href="/admin/products?edit=<?= (int) $p['id'] ?>">Edit</a><form method="post"><input type="hidden" name="csrf" value="<?=admin_h($csrfToken)?>"><button name="del" value="<?= (int) $p['id'] ?>">Hide</button></form></div></div><div class="product-row-meta"><strong>₦<?=number_format($p['price_kobo'] / 100, 2)?></strong><span><?=admin_h($p['active'] ? 'Live' : 'Hidden')?></span></div></div><?php endforeach; ?></div></section>
<?php admin_end(); ?>
